// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    RewardVault c;

    function setUp() public {
        c = new RewardVault();
    }

    function _run(address user) internal {
        vm.assume(user != address(0));
        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        assertTrue(!(!reverted && c.balance(user) == 0 && user.balance == 0));
    }

    function testFuzz_run(address user) public {
        _run(user);
    }

    receive() external payable {}
}
